  display: block;
  width: 100vw;
  height: 100vh;
  cursor: none;
}

/* HUD */
#hud {
  position: absolute;
  top: 0; left: 0; right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background: rgba(0,0,0,0.55);
  border-bottom: 1px solid rgba(0,255,180,0.2);
  z-index: 10;
  font-size: 14px;
  letter-spacing: 2px;
  pointer-events: none;
}

#hud span { color: #00ffb4; }
#hud span span { color: #fff; }
#health-display { color: #ff4455 !important; }
#health-display span { color: #fff; }

/* Crosshair */
#crosshair {
  position: absolute;
  width: 28px;
  height: 28px;
  pointer-events: none;
  z-index: 20;
  transform: translate(-50%, -50%);
  border: 2px solid rgba(0,255,180,0.85);
  border-radius: 50%;
}
#crosshair::before, #crosshair::after {
  content: '';
  position: absolute;
  background: rgba(0,255,180,0.85);
}
#crosshair::before {
  width: 2px; height: 8px;
  left: 50%; top: -5px;
  transform: translateX(-50%);
}
#crosshair::after {
  width: 8px; height: 2px;
  top: 50%; left: -5px;
  transform: translateY(-50%);
}

/* Overlay (start screen) */
#overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0.82);
  z-index: 50;
}
#overlay.hidden { display: none; }
#overlay.visible { display: flex; }

#menu {
  text-align: center;
  padding: 40px 50px;
  border: 1px solid rgba(0,255,180,0.3);
  background: rgba(0,20,30,0.9);
  border-radius: 6px;
  max-width: 480px;
  width: 90%;
}

.title {
  font-size: 42px;
  letter-spacing: 6px;
  color: #00ffb4;
  text-shadow: 0 0 20px #00ffb4;
  margin-bottom: 10px;
}

.subtitle {
  font-size: 13px;
  color: #aaa;
  margin-bottom: 24px;
  line-height: 1.6;
}

.controls-info {
  background: rgba(0,255,180,0.05);
  border: 1px solid rgba(0,255,180,0.15);
  border-radius: 4px;
  padding: 14px 20px;
  margin-bottom: 28px;
  text-align: left;
}
.controls-info p {
  font-size: 12px;
  color: #ccc;
  margin-bottom: 6px;
  letter-spacing: 1px;
}
.controls-info p:last-child { margin-bottom: 0; }
kbd {
  background: rgba(0,255,180,0.15);
  border: 1px solid rgba(0,255,180,0.4);
  border-radius: 3px;
  padding: 1px 5px;
  font-size: 11px;
  color: #00ffb4;
  font-family: inherit;
}

button {
  background: transparent;
  border: 2px solid #00ffb4;
  color: #00ffb4;
  font-family: 'Courier New', monospace;
  font-size: 15px;
  letter-spacing: 4px;
  padding: 12px 36px;
  cursor: pointer;
  border-radius: 4px;
  transition: background 0.15s, color 0.15s, box-shadow 0.15s;
}
button:hover {
  background: #00ffb4;
  color: #000;
  box-shadow: 0 0 18px #00ffb4;
}

/* Game over */
#gameover {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0.82);
  z-index: 50;
}
#gameover.hidden { display: none; }
#gameover-box {
  text-align: center;
  padding: 40px 50px;
  border: 1px solid rgba(255,60,80,0.4);
  background: rgba(20,0,0,0.9);
  border-radius: 6px;
  width: 90%;
  max-width: 380px;
}
#gameover-box h2 {
  font-size: 38px;
  color: #ff4455;
  letter-spacing: 6px;
  text-shadow: 0 0 18px #ff4455;
  margin-bottom: 20px;
}
#gameover-box p {
  font-size: 14px;
  color: #ccc;
  margin-bottom: 10px;
  letter-spacing: 1px;
}
#gameover-box button {
  border-color: #ff4455;
  color: #ff4455;
  margin-top: 20px;
}
#gameover-box button:hover {
  background: #ff4455;
  color: #000;
  box-shadow: 0 0 18px #ff4455;
}

/* Wave banner */
#wave-banner {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 36px;
  color: #00ffb4;
  letter-spacing: 8px;
  text-shadow: 0 0 24px #00ffb4;
  pointer-events: none;
  z-index: 30;
  opacity: 0;
  transition: opacity 0.4s;
}
#wave-banner.visible { opacity: 1; }
#wave-banner.hidden { display: none; }

/* Reload bar */
#reload-bar-container {
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  z-index: 20;
  pointer-events: none;
}
#reload-bar-container.hidden { display: none; }
#reload-bar-container span {
  font-size: 11px;
  color: #00ffb4;
  letter-spacing: 3px;
  display: block;
  margin-top: 4px;
