#reload-bar {
  width: 160px;
  height: 6px;
  background: rgba(0,255,180,0.15);
  border: 1px solid rgba(0,255,180,0.4);
  border-radius: 3px;
  overflow: hidden;
}
#reload-bar::after {
  content: '';
  display: block;
  height: 100%;
  background: #00ffb4;
  width: var(--progress, 0%);
  transition: width 0.05s linear;
  box-shadow: 0 0 6px #00ffb4;
}
