{"type": "sequential", "steps": [{"tool": "plan_update", "args": {"task_id": "t2", "status": "done"}}, {"tool": "file_write", "args": {"path": "C:\Users\TochukwuMba\Documents\Code\chika_v2\data\profiles\zoe\workspace\drone-game\game.js", "content": "// ─── DRONE STRIKE — game.js ───────────────────────────────────────────────
// Player is a drone. Targets fly around the sky. Shoot them down.
// Waves get harder. Lose all health → game over.

const canvas   = document.getElementById('gameCanvas');
const ctx      = canvas.getContext('2d');
const overlay  = document.getElementById('overlay');
const gameoverEl = document.getElementById('gameover');
const waveBanner = document.getElementById('wave-banner');
const reloadBar  = document.getElementById('reload-bar');
const reloadContainer = document.getElementById('reload-bar-container');

const elScore  = document.getElementById('score');
const elWave   = document.getElementById('wave');
const elAmmo   = document.getElementById('ammo');
const elHealth = document.getElementById('health');
const elFinalScore = document.getElementById('final-score');
const elFinalWave  = document.getElementById('final-wave');
const crosshair    = document.getElementById('crosshair');

// ── resize ──────────────────────────────────────────────────────────────────
function resize() {
  canvas.width  = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

// ── constants ───────────────────────────────────────────────────────────────
const DRONE_SPEED   = 4;
const BOOST_SPEED   = 8;
const BULLET_SPEED  = 14;
const MAX_AMMO      = 30;
const RELOAD_MS     = 2000;
const TARGET_TYPES  = [
  { color: '#ff4455', radius: 18, hp: 1, speed: 1.8, score: 10, label: 'SCOUT' },
  { color: '#ff8c00', radius: 24, hp: 2, speed: 1.2, score: 25, label: 'BOMBER' },
  { color: '#cc44ff', radius: 14, hp: 1, speed: 3.0, score: 40, label: 'FAST' },
  { color: '#00cfff', radius: 30, hp: 4, speed: 0.8, score: 60, label: 'TANK' },
];

// ── game state ───────────────────────────────────────────────────────────────
let state = {};
let keys  = {};
let mouse = { x: 0, y: 0, down: false };
let animId = null;
let lastTime = 0;
let reloading = false;
let reloadStart = 0;
let particles = [];
let explosions = [];
let running = false;

function initState() {
  resize();
  state = {
    drone: {
      x: canvas.width  / 2,
      y: canvas.height / 2,
      w: 44, h: 28,
      vx: 0, vy: 0,
      angle: 0,
      boosting: false,
      invincible: 0,  // ms remaining of invincibility after hit
    },
    bullets:  [],
    targets:  [],
    score:    0,
    health:   5,
    ammo:     MAX_AMMO,
    wave:     1,
    waveKills: 0,
    waveTarget: 8,
    wavePause: false,
  };
  particles  = [];
  explosions = [];
  reloading  = false;
  reloadContainer.classList.add('hidden');
  updateHUD();
}

// ── HUD ──────────────────────────────────────────────────────────────────────
function updateHUD() {
  elScore.textContent  = state.score;
  elWave.textContent   = state.wave;
  elAmmo.textContent   = reloading ? 'RELOADING' : state.ammo;
  elHealth.textContent = state.health;
}

// ── wave management ──────────────────────────────────────────────────────────
function spawnWave() {
  const w    = state.wave;
  const count = state.waveTarget;
  const pool  = w <= 1 ? [0] : w <= 2 ? [0,1] : w <= 4 ? [0,1,2] : [0,1,2,3];

  for (let i = 0; i < count; i++) {
    const tType = TARGET_TYPES[ pool[Math.floor(Math.random() * pool.length)] ];
    spawnTarget(tType);
  }
}

function spawnTarget(tType) {
  // Spawn outside the visible area
  const side = Math.floor(Math.random() * 4);
  let x, y;
  const m = 60;
  if (side === 0) { x = Math.random() * canvas.width; y = -m; }
  else if (side === 1) { x = canvas.width + m; y = Math.random() * canvas.height; }
  else if (side === 2) { x = Math.random() * canvas.width; y = canvas.height + m; }
  else { x = -m; y = Math.random() * canvas.height; }

  const angle = Math.atan2(canvas.height/2 - y, canvas.width/2 - x) + (Math.random()-0.5)*0.8;
  const speed = tType.speed * (1 + state.wave * 0.08);

  state.targets.push({
    x, y,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    r: tType.radius,
    hp: tType.hp,
    maxHp: tType.hp,
    color: tType.color,
    score: tType.score,
    label: tType.label,
    angle: angle,
    wobble: Math.random() * Math.PI * 2,
    wobbleSpeed: 0.02 + Math.random() * 0.03,
  });
}

function checkWaveComplete() {
  if (state.targets.length === 0 && !state.wavePause) {
    state.wavePause = true;
    showWaveBanner(`WAVE ${state.wave} CLEAR!`, () => {
      state.wave++;
      state.waveTarget = 8 + (state.wave - 1) * 4;
      state.waveKills  = 0;
      state.wavePause  = false;
      elWave.textContent = state.wave;
      spawnWave();
      showWaveBanner(`WAVE ${state.wave}`, null);
    });
  }
}

function showWaveBanner(text, cb) {
  waveBanner.textContent = text;
  waveBanner.classList.remove('hidden');
  waveBanner.classList.add('visible');
  setTimeout(() => {
    waveBanner.classList.remove('visible');
    setTimeout(() => {
      waveBanner.classList.add('hidden');
      if (cb) cb();
    }, 500);
  }, 1800);
}

// ── input ────────────────────────────────────────────────────────────────────
window.addEventListener('keydown', e => {
  keys[e.code] = true;
  if (e.code === 'KeyR' && !reloading && state.ammo < MAX_AMMO && running) startReload();
  if (e.code === 'Space') e.preventDefault();
});
window.addEventListener('keyup',  e => { keys[e.code] = false; });

window.addEventListener('mousemove', e => {
  mouse.x = e.clientX;
  mouse.y = e.clientY;
  crosshair.style.left = e.clientX + 'px';
  crosshair.style.top  = e.clientY + 'px';
});

window.addEventListener('mousedown', e => {
  if (!running) return;
  mouse.down = true;
  shoot();
});
window.addEventListener('mouseup', () => { mouse.down = false; });

// ── shooting ─────────────────────────────────────────────────────────────────
let shootCooldown = 0;
function shoot() {
  if (!running || reloading || state.ammo <= 0 || shootCooldown > 0) return;
  const d = state.drone;
  const angle = Math.atan2(mouse.y - d.y, mouse.x - d.x);
  state.bullets.push({
    x: d.x + Math.cos(angle) * 24,
    y: d.y + Math.sin(angle) * 24,
    vx: Math.cos(angle) * BULLET_SPEED,
    vy: Math.sin(angle) * BULLET_SPEED,
    age: 0,
  });
  state.ammo--;
  updateHUD();
  shootCooldown = 100; // ms
  if (state.ammo <= 0) startReload();
  // muzzle flash particles
  for (let i = 0; i < 5; i++) {
    particles.push({
      x: d.x + Math.cos(angle)*24, y: d.y + Math.sin(angle)*24,
      vx: Math.cos(angle + (Math.random()-0.5)*0.8) * (2+Math.random()*3),
      vy: Math.sin(angle + (Math.random()-0.5)*0.8) * (2+Math.random()*3),
      life: 0.3 + Math.random()*0.2, maxLife: 0.5,
      color: '#ffdd44', radius: 2+Math.random()*2,
    });
  }
}

function startReload() {
  if (reloading) return;
  reloading = true;
  reloadStart = performance.now();
  reloadContainer.classList.remove('hidden');
  updateHUD();
}

function tickReload(now) {
  if (!reloading) return;
  const pct = Math.min(1, (now - reloadStart) / RELOAD_MS);
  reloadBar.style.setProperty('--progress', (pct * 100) + '%');
  if (pct >= 1) {
    reloading = false;
    state.ammo = MAX_AMMO;
    reloadContainer.classList.add('hidden');
    updateHUD();
  }
}

// ── update ───────────────────────────────────────────────────────────────────
function update(dt, now) {
  shootCooldown = Math.max(0, shootCooldown - dt);
  tickReload(now);

  // ── drone movement
  const d = state.drone;
  const boost = keys['Space'];
  const spd   = boost ? BOOST_SPEED : DRONE_SPEED;
  let dx = 0, dy = 0;
  if (keys['KeyW'] || keys['ArrowUp'])    dy -= 1;
  if (keys['KeyS'] || keys['ArrowDown'])  dy += 1;
  if (keys['KeyA'] || keys['ArrowLeft'])  dx -= 1;
  if (keys['KeyD'] || keys['ArrowRight']) dx += 1;

  if (dx !== 0 || dy !== 0) {
    const len = Math.sqrt(dx*dx + dy*dy);
    d.vx = (dx/len) * spd;
    d.vy = (dy/len) * spd;
  } else {
    d.vx *= 0.85;
    d.vy *= 0.85;
  }

  d.x = Math.max(d.w/2, Math.min(canvas.width  - d.w/2, d.x + d.vx));
  d.y = Math.max(d.h/2, Math.min(canvas.height - d.h/2, d.y + d.vy));

  // drone faces the mouse
  d.angle = Math.atan2(mouse.y - d.y, mouse.x - d.x);
  d.boosting = boost;

  if (d.invincible > 0) d.invincible -= dt;

  // ── bullets
  for (let i = state.bullets.length - 1; i >= 0; i--) {
    const b = state.bullets[i];
    b.x += b.vx;
    b.y += b.vy;
    b.age += dt;
    if (b.x < -20 || b.x > canvas.width+20 || b.y < -20 || b.y > canvas.height+20 || b.age > 3000) {
      state.bullets.splice(i, 1);
    }
  }

  // ── targets
  for (let i = state.targets.length - 1; i >= 0; i--) {
    const t = state.targets[i];
    t.wobble += t.wobbleSpeed;
    // slight steering toward drone
    const toX = d.x - t.x;
    const toY = d.y - t.y;
    const dist = Math.sqrt(toX*toX + toY*toY) || 1;
    const steerStrength = 0.012;
    t.vx += (toX/dist) * steerStrength * (1 + state.wave * 0.05);
    t.vy += (toY/dist) * steerStrength * (1 + state.wave * 0.05);
    // cap speed
    const speed = Math.sqrt(t.vx*t.vx + t.vy*t.vy);
    const maxSpd = TARGET_TYPES.find(tt => tt.label === t.label)?.speed * (1 + state.wave * 0.08) || 3;
    if (speed > maxSpd) { t.vx = (t.vx/speed)*maxSpd; t.vy = (t.vy/speed)*maxSpd; }

    t.x += t.vx;
    t.y += t.vy;

    // ── bullet-target collision
    let hit = false;
    for (let j = state.bullets.length - 1; j >= 0; j--) {
      const b = state.bullets[j];
      const ex = b.x - t.x, ey = b.y - t.y;
      if (ex*ex + ey*ey < (t.r+4)*(t.r+4)) {
        state.bullets.splice(j, 1);
        t.hp--;
        hit = true;
        // hit spark
        for (let k = 0; k < 8; k++) {
          const a = Math.random() * Math.PI * 2;
          const spd2 = 1 + Math.random() * 3;
          particles.push({ x: b.x, y: b.y,
            vx: Math.cos(a)*spd2, vy: Math.sin(a)*spd2,
            life: 0.4, maxLife: 0.4,
            color: t.color, radius: 3 });
        }
        if (t.hp <= 0) {
          spawnExplosion(t.x, t.y, t.r, t.color);
          state.score += t.score * state.wave;
          state.waveKills++;
          state.targets.splice(i, 1);
          updateHUD();
          break;
        }
      }
    }

    // ── drone-target collision
    if (!hit && d.invincible <= 0) {
      const ex = d.x - t.x, ey = d.y - t.y;
      if (ex*ex + ey*ey < (t.r + 20)*(t.r + 20)) {
        state.health--;
        d.invincible = 1500; // 1.5s invincibility
        updateHUD();
        spawnExplosion(d.x, d.y, 32, '#ff4455');
        if (state.health <= 0) {
          endGame();
          return;
        }
      }
    }
  }

  // ── particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;  p.y += p.vy;
    p.vx *= 0.92; p.vy *= 0.92;
    p.life -= dt / 1000;
    if (p.life <= 0) particles.splice(i, 1);
  }

  // ── explosions
  for (let i = explosions.length - 1; i >= 0; i--) {
    const e = explosions[i];
    e.age += dt;
    if (e.age >= e.duration) explosions.splice(i, 1);
  }

  // auto-shoot on hold
  if (mouse.down) shoot();

  checkWaveComplete();
}

function spawnExplosion(x, y, r, color) {
  explosions.push({ x, y, r, color, age: 0, duration: 500 });
  for (let i = 0; i < 20; i++) {
    const a = Math.random() * Math.PI * 2;
    const spd = 1.5 + Math.random() * 4;
    particles.push({
      x, y,
      vx: Math.cos(a)*spd, vy: Math.sin(a)*spd,
      life: 0.6 + Math.random()*0.4, maxLife: 1.0,
      color: color, radius: 3 + Math.random()*3,
    });
  }
}

// ── draw ─────────────────────────────────────────────────────────────────────
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawBackground();
  drawExplosions();
  drawTargets();
  drawBullets();
  drawDrone();
  drawParticles();
}

function drawBackground() {
  // gradient sky
  const grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
  grad.addColorStop(0, '#000d1a');
  grad.addColorStop(1, '#001428');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // grid lines (parallax feel)
  ctx.strokeStyle = 'rgba(0,255,180,0.04)';
  ctx.lineWidth = 1;
  const gridSize = 60;
  for (let x = 0; x < canvas.width;  x += gridSize) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x, canvas.height); ctx.stroke(); }
  for (let y = 0; y < canvas.height; y += gridSize) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(canvas.width, y); ctx.stroke(); }

  // stars
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  // deterministic stars using a seeded pattern
  for (let i = 0; i < 120; i++) {
    const sx = ((i * 137 + 50) % canvas.width);
    const sy = ((i * 97  + 30) % canvas.height);
    ctx.beginPath();
    ctx.arc(sx, sy, 0.8, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawDrone() {
  const d = state.drone;
  // blink when invincible
  if (d.invincible > 0 && Math.floor(d.invincible / 150) % 2 === 0) return;

  ctx.save();
  ctx.translate(d.x, d.y);
  ctx.rotate(d.angle);

  // engine glow
  const glow = ctx.createRadialGradient(-18, 0, 2, -18, 0, 22);
  glow.addColorStop(0, d.boosting ? 'rgba(0,200,255,0.7)' : 'rgba(0,255,180,0.4)');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = glow;
  ctx.beginPath(); ctx.arc(-18, 0, 22, 0, Math.PI*2); ctx.fill();

  // body
  ctx.fillStyle = '#1a2a3a';
  ctx.strokeStyle = '#00ffb4';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(22, 0);
  ctx.lineTo(-14, -10);
  ctx.lineTo(-18, 0);
  ctx.lineTo(-14,  10);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // cockpit dome
  ctx.fillStyle = 'rgba(0,200,255,0.5)';
  ctx.strokeStyle = 'rgba(0,255,180,0.7)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(4, 0, 7, 5, 0, 0, Math.PI*2);
  ctx.fill();
  ctx.stroke();

  // arms
  ctx.strokeStyle = '#00ffb4';
  ctx.lineWidth = 2;
  [[-4, -12], [-4, 12], [-10, -8], [-10, 8]].forEach(([ax, ay]) => {
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(ax, ay); ctx.stroke();
    // rotor
    ctx.fillStyle = 'rgba(0,255,180,0.3)';
    ctx.strokeStyle = 'rgba(0,255,180,0.8)';
    ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.arc(ax, ay, 5, 0, Math.PI*2); ctx.fill(); ctx.stroke();
  });

  // cannon
  ctx.fillStyle = '#00ffb4';
  ctx.beginPath();
  ctx.rect(12, -2.5, 14, 5);
  ctx.fill();

  ctx.restore();
}

function drawBullets() {
  state.bullets.forEach(b => {
    const angle = Math.atan2(b.vy, b.vx);
    ctx.save();
    ctx.translate(b.x, b.y);
    ctx.rotate(angle);
    // glow
    const g = ctx.createRadialGradient(0,0,1,0,0,8);
    g.addColorStop(0, 'rgba(0,255,180,0.9)');
    g.addColorStop(1, 'rgba(0,255,180,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0,0,8,0,Math.PI*2); ctx.fill();
    // tracer
    ctx.strokeStyle = '#00ffb4';
    ctx.lineWidth = 2;
    ctx.shadowColor = '#00ffb4';
    ctx.shadowBlur = 8;
    ctx.beginPath(); ctx.moveTo(-8, 0); ctx.lineTo(0, 0); ctx.stroke();
    ctx.restore();
  });
}

function drawTargets() {
  state.targets.forEach(t => {
    ctx.save();
    ctx.translate(t.x, t.y);

    // outer ring pulse
    const pulse = 0.5 + 0.5 * Math.sin(t.wobble * 3);
    ctx.beginPath();
    ctx.arc(0, 0, t.r + 6 * pulse, 0, Math.PI*2);
    ctx.strokeStyle = t.color;
    ctx.globalAlpha = 0.25 + 0.2 * pulse;
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.globalAlpha = 1;

    // body glow
    const glow = ctx.createRadialGradient(0,0,0,0,0,t.r);
    glow.addColorStop(0, t.color);
    glow.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(0,0,t.r,0,Math.PI*2); ctx.fill();

    // body
    ctx.fillStyle = t.color;
    ctx.globalAlpha = 0.6;
    ctx.beginPath();
    const sides = t.label === 'TANK' ? 6 : t.label === 'BOMBER' ? 5 : t.label === 'FAST' ? 3 : 4;
    const startA = t.wobble;
    for (let i = 0; i < sides; i++) {
      const a = startA + (i / sides) * Math.PI * 2;
      i === 0 ? ctx.moveTo(Math.cos(a)*t.r, Math.sin(a)*t.r)
              : ctx.lineTo(Math.cos(a)*t.r, Math.sin(a)*t.r);
    }
    ctx.closePath(); ctx.fill();
    ctx.globalAlpha = 1;
    ctx.strokeStyle = t.color;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // hp bar
    if (t.hp < t.maxHp) {
      const bw = t.r * 2, bh = 4;
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(-bw/2, -t.r - 10, bw, bh);
      ctx.fillStyle = t.color;
      ctx.fillRect(-bw/2, -t.r - 10, bw * (t.hp/t.maxHp), bh);
    }

    ctx.restore();
  });
}

function drawExplosions() {
  explosions.forEach(e => {
    const p   = e.age / e.duration;
    const r   = e.r * (1 + p * 2);
    const alpha = 1 - p;
    const glow = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, r);
    glow.addColorStop(0,   `rgba(255,255,200,${alpha})`);
    glow.addColorStop(0.3, e.color.replace(')', `,${alpha*0.8})`).replace('rgb', 'rgba'));
    glow.addColorStop(1,   'rgba(0,0,0,0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(e.x, e.y, r, 0, Math.PI*2);
    ctx.fill();
  });
}

function drawParticles() {
  particles.forEach(p => {
    const a = Math.max(0, p.life / p.maxLife);
    ctx.globalAlpha = a;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius * a, 0, Math.PI*2);
    ctx.fill();
  });
  ctx.globalAlpha = 1;
}

// ── game loop ─────────────────────────────────────────────────────────────────
function loop(timestamp) {
  if (!running) return;
  const dt = Math.min(timestamp - lastTime, 50); // cap dt to avoid spiral
  lastTime = timestamp;
  update(dt, timestamp);
  draw();
  animId = requestAnimationFrame(loop);
}

function startGame() {
  overlay.classList.add('hidden');
  overlay.classList.remove('visible');
  gameoverEl.classList.add('hidden');
  initState();
  running = true;
  spawnWave();
  showWaveBanner('WAVE 1', null);
  lastTime = performance.now();
  animId = requestAnimationFrame(loop);
}

function endGame() {
  running = false;
  cancelAnimationFrame(animId);
  elFinalScore.textContent = state.score;
  elFinalWave.textContent  = state.wave;
  gameoverEl.classList.remove('hidden');
}

// ── buttons ───────────────────────────────────────────────────────────────────
document.getElementById('startBtn').addEventListener('click',   startGame);
document.getElementById('restartBtn').addEventListener('click', startGame);

// init crosshair at center
crosshair.style.left = (window.innerWidth/2)  + 'px';
crosshair.style.top  = (window.innerHeight/2) + 'px';

// Draw idle background while on menu
(function idleLoop() {
  if (running) return;
  drawBackground();
  requestAnimationFrame(idleLoop);
})();
"}, "store_result_as": "$js_done"}]}

