function checkWaveDone() {
  if (gs.enemies.filter(e => e.alive).length === 0 && !gs.wavePending) {
    gs.wavePending = true;
    showBanner('WAVE ' + gs.wave + '  CLEAR', 2000);
    setTimeout(() => {
      gs.wave++;
      gs.wavePending = false;
      startWave();
