// ── HUD update ────────────────────────────────────────────────
const MAX_HP = 100;
function updateHUD() {
  elScore.textContent  = gs.score;
  elWave.textContent   = gs.wave;
  elKills.textContent  = gs.kills;
  elAmmo.textContent   = gs.reloading ? 'RELOADING...' : gs.ammo + ' / ' + MAX_AMMO;
  elAlt.textContent    = Math.round(gs.drone.position.y) + 'm';
